import React from 'react';
import Profile from "./Profile";
import {connect} from "react-redux";
import {getStatus, getUserProfile, setCurrentId, updateStatus, savePhoto} from "../../redux/profileReducer";
import {useLocation, useNavigate, useParams} from "react-router-dom";
import {withAuthRedirect} from "../../hoc/withAuthRedirect";
import {compose} from "redux";

class ProfileContainer extends React.Component {
    constructor(props) {
        super(props)
        this.props.setCurrentId();
    }

    state = {
        isOwner: false,
    }




    shouldComponentUpdate(nextProps, nextState) {
        return (nextProps !== this.props || nextState !== this.state);
    }

    f

    componentDidMount() {
        const userId = this.props.router.params.userId || this.props.myId;
        this.setState({isOwner: userId === this.props.myId});
        if (userId) {
            this.fetchProfile(userId);
        } else {
            console.error("User ID is not available");
        }
    }

    componentDidUpdate(prevProps) {
        if (this.props.myId !== prevProps.myId || this.props.router.params.userId !== prevProps.router.params.userId) {
            this.fetchProfileIfNeeded();
        }
    }

    fetchProfileIfNeeded() {
        const userId = this.props.myId || this.props.router.params.userId;
        if (userId) {
            this.fetchProfile(userId);
        } else {
            console.error("User ID is not available");
        }
    }


    fetchProfile(userId) {
        if (userId) {
            this.props.getUserProfile(userId)
            this.props.getStatus(userId)

        } else {
            console.error("fetchProfile called without userId");
        }

    }


    render() {
        console.log('myID ', this.props.myId)
        return (
            <Profile {...this.props}
                     isOwner={this.state.isOwner}
                     myId={this.props.myId} profile={this.props.profile} status={this.props.status}
                     updateStatus={this.props.updateStatus}/>
        )
    }
}


export function withRouter(Component) {
    function ComponentWithRouterProp(props) {
        let location = useLocation();
        let navigate = useNavigate();
        let params = useParams();
        return (
            <Component
                {...props}
                router={{location, navigate, params}}
            />
        );
    }

    return ComponentWithRouterProp;
}


let mapStateToProps = (state) => ({
    profile: state.profilePage.profile,
    status: state.profilePage.status,
    myId: state.profilePage.myId,
})


export default compose(
    connect(mapStateToProps, {getUserProfile, setCurrentId, getStatus, updateStatus, savePhoto}),
    withRouter,
    withAuthRedirect
)(ProfileContainer)
